changeSet.sql:
ALTER TABLE mentor_conversation ADD CONSTRAINT chk_mentor_conversation_thread
    CHECK ((parent_conversation_id IS NULL) = (parent_entry_id IS NULL));
ALTER TABLE mentor_conversation ADD CONSTRAINT chk_mentor_conversation_slack
    CHECK ((slack_team_id IS NULL AND slack_user_id IS NULL AND slack_channel_id IS NULL)
        OR (slack_team_id IS NOT NULL AND slack_user_id IS NOT NULL AND slack_channel_id IS NOT NULL
            AND parent_conversation_id IS NULL));
ALTER TABLE mentor_entry ADD CONSTRAINT chk_mentor_entry_kind
    CHECK (kind IN ('USER', 'HEPH', 'TOOL_RESULT', 'SYSTEM', 'SUMMARY', 'DIGEST'));
ALTER TABLE mentor_entry ADD CONSTRAINT chk_mentor_entry_surface
    CHECK (surface IN ('APP', 'SLACK', 'SYSTEM'));
ALTER TABLE mentor_entry ADD CONSTRAINT chk_mentor_entry_slack_delivery
    CHECK (slack_delivery IS NULL OR slack_delivery IN ('PENDING', 'DELIVERED', 'UNCERTAIN', 'FAILED'));
ALTER TABLE mentor_entry ADD CONSTRAINT chk_mentor_entry_vote
    CHECK (vote IS NULL OR vote IN ('HELPFUL', 'NOT_HELPFUL'));
ALTER TABLE mentor_entry ADD CONSTRAINT chk_mentor_entry_payload_shape
    CHECK (payload IS NULL OR jsonb_typeof(payload) = 'object');
ALTER TABLE mentor_turn ADD CONSTRAINT chk_mentor_turn_status
    CHECK (status IN ('QUEUED', 'RUNNING', 'DONE', 'FAILED', 'STOPPED'));
ALTER TABLE mentor_turn ADD CONSTRAINT chk_mentor_turn_surface
    CHECK (surface IN ('APP', 'SLACK'));

CREATE UNIQUE INDEX ux_mentor_conversation_main ON mentor_conversation (workspace_id, account_id)
    WHERE parent_conversation_id IS NULL;
CREATE INDEX idx_mentor_conversation_slack ON mentor_conversation (slack_user_id, slack_team_id)
    WHERE slack_user_id IS NOT NULL;
CREATE UNIQUE INDEX ux_mentor_entry_request ON mentor_entry (request_id) WHERE request_id IS NOT NULL;
CREATE INDEX ix_mentor_entry_text_search ON mentor_entry USING gin (to_tsvector('simple'::regconfig, search_text))
    WHERE kind IN ('USER', 'HEPH', 'DIGEST');
CREATE INDEX ix_mentor_entry_slack_question_unsettled ON mentor_entry (turn_id)
    WHERE kind = 'USER' AND surface = 'SLACK'
        AND (slack_delivery IS NULL OR slack_delivery IN ('PENDING', 'UNCERTAIN'));
CREATE INDEX ix_mentor_entry_digest_unsettled ON mentor_entry (created_at)
    WHERE kind = 'DIGEST' AND slack_delivery IN ('PENDING', 'UNCERTAIN');
CREATE INDEX idx_feedback_copy_mentor_turn ON feedback_copy (mentor_turn_id)
    WHERE mentor_turn_id IS NOT NULL;
CREATE UNIQUE INDEX ux_mentor_turn_running ON mentor_turn (conversation_id) WHERE status = 'RUNNING';
CREATE INDEX idx_mentor_turn_leased_until ON mentor_turn (leased_until) WHERE leased_until IS NOT NULL;
ALTER TABLE mentor_turn SET (fillfactor = 50);

ALTER TABLE mentor_conversation ADD CONSTRAINT sfk_mentor_conversation_workspace
    FOREIGN KEY (workspace_id) REFERENCES workspace (id) ON DELETE RESTRICT;
ALTER TABLE mentor_conversation ADD CONSTRAINT sfk_mentor_conversation_account
    FOREIGN KEY (account_id) REFERENCES account (id) ON DELETE RESTRICT;
ALTER TABLE mentor_conversation ADD CONSTRAINT sfk_mentor_conversation_parent
    FOREIGN KEY (parent_conversation_id, workspace_id) REFERENCES mentor_conversation (id, workspace_id)
    ON DELETE CASCADE;
ALTER TABLE mentor_entry ADD CONSTRAINT sfk_mentor_entry_workspace
    FOREIGN KEY (workspace_id) REFERENCES workspace (id) ON DELETE RESTRICT;
ALTER TABLE mentor_entry ADD CONSTRAINT sfk_mentor_entry_conversation
    FOREIGN KEY (conversation_id, workspace_id) REFERENCES mentor_conversation (id, workspace_id)
    ON DELETE CASCADE;
ALTER TABLE mentor_conversation ADD CONSTRAINT sfk_mentor_conversation_parent_entry
    FOREIGN KEY (parent_entry_id, workspace_id) REFERENCES mentor_entry (id, workspace_id) ON DELETE CASCADE;
ALTER TABLE mentor_turn ADD CONSTRAINT sfk_mentor_turn_workspace
    FOREIGN KEY (workspace_id) REFERENCES workspace (id) ON DELETE RESTRICT;
ALTER TABLE mentor_turn ADD CONSTRAINT sfk_mentor_turn_conversation
    FOREIGN KEY (conversation_id, workspace_id) REFERENCES mentor_conversation (id, workspace_id)
    ON DELETE CASCADE;
ALTER TABLE mentor_entry ADD CONSTRAINT sfk_mentor_entry_turn
    FOREIGN KEY (turn_id, workspace_id) REFERENCES mentor_turn (id, workspace_id) ON DELETE SET NULL (turn_id);
ALTER TABLE feedback_copy ADD CONSTRAINT sfk_feedback_copy_mentor_entry
    FOREIGN KEY (mentor_entry_id, workspace_id) REFERENCES mentor_entry (id, workspace_id)
    ON DELETE SET NULL (mentor_entry_id);
ALTER TABLE feedback_copy ADD CONSTRAINT sfk_feedback_copy_mentor_turn
    FOREIGN KEY (mentor_turn_id, workspace_id) REFERENCES mentor_turn (id, workspace_id)
    ON DELETE SET NULL (mentor_turn_id);

CREATE OR REPLACE FUNCTION guard_feedback_copy_fence() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE shown_text text;
BEGIN
 IF OLD.write_started_at IS NOT NULL THEN
  IF NEW.write_started_at IS DISTINCT FROM OLD.write_started_at OR
     ROW(NEW.id,NEW.workspace_id,NEW.feedback_id,NEW.position,NEW.write_key,NEW.write_marker,NEW.path,NEW.start_line,NEW.end_line,NEW.side)
     IS DISTINCT FROM ROW(OLD.id,OLD.workspace_id,OLD.feedback_id,OLD.position,OLD.write_key,OLD.write_marker,OLD.path,OLD.start_line,OLD.end_line,OLD.side) THEN
   RAISE EXCEPTION 'physical write fence is immutable' USING ERRCODE='55000';
  END IF;
  IF NEW.mentor_turn_id IS DISTINCT FROM OLD.mentor_turn_id AND NOT
     (NEW.mentor_turn_id IS NULL AND NOT EXISTS(SELECT 1 FROM mentor_turn WHERE id=OLD.mentor_turn_id AND workspace_id=OLD.workspace_id)) THEN
   RAISE EXCEPTION 'conversation turn binding is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.mentor_entry_id IS NOT NULL AND NEW.mentor_entry_id IS DISTINCT FROM OLD.mentor_entry_id AND NOT
     (NEW.mentor_entry_id IS NULL AND NOT EXISTS(SELECT 1 FROM mentor_entry WHERE id=OLD.mentor_entry_id AND workspace_id=OLD.workspace_id)) THEN
   RAISE EXCEPTION 'conversation answer binding is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.mentor_entry_id IS NULL AND NEW.mentor_entry_id IS NOT NULL AND OLD.posted_at IS NOT NULL THEN
   RAISE EXCEPTION 'conversation answer binding is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.mentor_entry_id IS NULL AND NEW.mentor_entry_id IS NOT NULL AND NOT EXISTS(
     SELECT 1 FROM mentor_entry e JOIN mentor_conversation c ON(c.id,c.workspace_id)=(e.conversation_id,e.workspace_id)
     JOIN feedback f ON(f.id,f.workspace_id)=(NEW.feedback_id,NEW.workspace_id) AND f.developer_id=c.account_id
     WHERE e.id=NEW.mentor_entry_id AND e.workspace_id=NEW.workspace_id AND e.kind='HEPH' AND e.turn_id=NEW.mentor_turn_id) THEN
   RAISE EXCEPTION 'conversation answer must be the claiming turn answer to its developer' USING ERRCODE='23514';
  END IF;
  IF NEW.body IS DISTINCT FROM OLD.body THEN
   IF NOT(OLD.kind='CHAT_TURN' AND OLD.body IS NULL AND NEW.body IS NOT NULL AND
          OLD.posted_at IS NULL AND NEW.posted_at IS NOT NULL AND NEW.posted_at>=OLD.write_started_at AND
          OLD.state IN('WRITE_STARTED','FAILED') AND NEW.state='POSTED' AND
          NEW.mentor_entry_id IS NOT NULL AND NEW.mentor_turn_id IS NOT NULL) THEN
    RAISE EXCEPTION 'physical copy words are immutable' USING ERRCODE='55000';
   END IF;
   shown_text := conversation_receipt_words(NEW.workspace_id,NEW.feedback_id,NEW.mentor_entry_id,NEW.mentor_turn_id);
   IF shown_text IS NULL OR shown_text ~ '^[[:space:]]*$' OR NEW.body IS DISTINCT FROM shown_text THEN
    RAISE EXCEPTION 'conversation receipt must contain the words the completed answer showed' USING ERRCODE='23514';
   END IF;
  END IF;
  IF OLD.kind='CHAT_TURN' AND OLD.posted_at IS NULL AND NEW.posted_at IS NOT NULL AND NEW.body IS NULL THEN
   RAISE EXCEPTION 'conversation receipt requires actual words' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.write_started_at IS NOT NULL AND NEW.kind='CHAT_TURN' THEN
  IF NEW.body IS NOT NULL OR NEW.state<>'WRITE_STARTED' OR NOT EXISTS(
     SELECT 1 FROM mentor_turn t JOIN mentor_conversation c ON(c.id,c.workspace_id)=(t.conversation_id,t.workspace_id)
     JOIN feedback f ON(f.id,f.workspace_id)=(NEW.feedback_id,NEW.workspace_id) AND f.developer_id=c.account_id
     WHERE t.id=NEW.mentor_turn_id AND t.workspace_id=NEW.workspace_id AND t.status='RUNNING' AND f.destination='CONVERSATION') THEN
   RAISE EXCEPTION 'conversation fence requires a running Heph turn of its developer' USING ERRCODE='23514';
  END IF;
 END IF;
 IF OLD.kind<>NEW.kind AND NOT(OLD.kind='LINE_NOTE' AND NEW.kind='FILE_NOTE') THEN RAISE EXCEPTION 'copy form cannot change except acknowledged fallback' USING ERRCODE='55000'; END IF;
 IF OLD.external_ref IS NOT NULL AND NEW.external_ref IS DISTINCT FROM OLD.external_ref OR OLD.external_url IS NOT NULL AND NEW.external_url IS DISTINCT FROM OLD.external_url OR OLD.posted_at IS NOT NULL AND NEW.posted_at IS DISTINCT FROM OLD.posted_at THEN RAISE EXCEPTION 'physical write receipt is immutable' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$
